function markPlanDirty({autosave=true}={}){planRevision++;planDirty=true;if(roundActive)buildRoundSequence();renderPlan();clearTimeout(planSaveTimer);if(autosave)planSaveTimer=setTimeout(()=>savePlan({quiet:true}),700)}
