async function loadPlan(date=localDateKey(),{quiet=false,force=false}={}){if(!force&&date===dayPlan.date&&planDirty){renderPlan();return false}if(!force&&(planConflictDates.has(date)||planHasPending(date))){clearTimeout(planSaveTimer);const cached=loadJson(PLAN_CACHE_PREFIX+date,null);dayPlan=cached||{date,plan:null,items:[]};dayPlan.date=date;planDirty=false;planRevision++;renderPlan();return false}clearTimeout(planSaveTimer);dayPlan.date=date;try{const data=await api('GET',`/api/plan?date=${encodeURIComponent(date)}`);dayPlan={date,plan:data.plan||null,items:Array.isArray(data.items)?data.items:[]};saveJson(PLAN_CACHE_PREFIX+date,dayPlan);planDirty=false;planConflictDates.delete(date);planRevision++;planLastSyncedAt=Date.now();if(selectedSpotId&&!dayPlan.items.some(i=>i.id===selectedSpotId&&i.kind==='spot'))selectedSpotId=null;renderPlan();if(!quiet)toast('Plan hämtad');return true}catch(error){if(error?.status===401)return false;const cached=loadJson(PLAN_CACHE_PREFIX+date,null);if(cached){dayPlan=cached;planDirty=false;planRevision++;renderPlan();if(!quiet)toast('Visar lokalt sparad plan')}else{dayPlan={date,plan:null,items:[]};planDirty=false;planRevision++;renderPlan();if(!quiet)toast('Kunde inte hämta plan')}return false}}
